/**
 * GRID SYSTEM
 * 
 * WAÅ»NA INFORMACJA O MEDIA QUERIES I RESPONSYWNOÅšCI:
 * W tym pliku stosujemy specjalny wzorzec "mediaplex" dla media queries.
 * Zamiast zagnieÅ¼dÅ¼aÄ‡ media queries w pÄ™tlach generujÄ…cych klasy,
 * grupujemy wszystkie style dla danego breakpointu razem.
 * 
 * KorzyÅ›ci:
 * 1. Zapewnia to prawidÅ‚owÄ… kolejnoÅ›Ä‡ w wygenerowanym CSS:
 *    - Najpierw podstawowe klasy (bez breakpointÃ³w)
 *    - NastÄ™pnie klasy dla najwiÄ™kszego breakpointu (xl)
 *    - Na koÅ„cu klasy dla najmniejszego breakpointu (xxs)
 * 
 * 2. DziÄ™ki temu style dla mniejszych breakpointÃ³w (np. sm)
 *    sÄ… pÃ³Åºniej w CSS i poprawnie nadpisujÄ… style dla wiÄ™kszych (np. lg)
 * 
 * Kluczowe jest zachowanie porzÄ…dku od najwiÄ™kszego do najmniejszego breakpointu
 * w mapie $breakpoints oraz generowanie oddzielnych blokÃ³w @media dla kaÅ¼dego breakpointu.
 */


%grid {
    display: grid;
    grid-template-columns: minmax(1rem, 1fr) repeat(12, minmax(0, calc((#{$page-width} - 11 * #{$page-gap}) / 12))) minmax(1rem, 1fr);
    gap: $page-gap;
    row-gap: 0;
    @include media($breakpoint-sm) {
        gap: 0;
        row-gap: 16px;
    }
}

.flex {
    display: flex;
}

.grid-l-50 {
    grid-column: 1/8;
    grid-row: 1/2;
}

.grid-p-50 {
    grid-column: 8/15;
    grid-column: 1/2;
}

.grid {
    @extend %grid;
}

.align-center {
    align-items: center;
}
.justify-center {
    justify-content: center;
}
.align-start {
    align-items: start;
}
.justify-start {
    justify-content: start;
}
.align-end {
    align-items: end;
}
.justify-end {
